#!/bin/bash
# Regression of the vector-unit blocks (has/gvu_*.h) in a working tree: unit testbenches, then the instruction path
# (transformer check, window D, AVG_POOL). Run from the repository root on the Linux machine:
#   bash tools/has/regress_gvu.sh [out dir] [--unit-only]
# Reference values: window D 1658986 cycles, AVG_POOL 8/8, transformer check 14/14; with HAS_SPEC=v47ref (the configuration
# before the MAS) the transformer check takes 250885 vector-unit cycles; padding check program 13/13 with the padding
# staged by the data flow controller and with the padding generated by the IFMAP feeder (30 core passes); short-context
# layers 19/19; dilation layers 13/13 both ways (core busy 247370 / 247378); random dilation layers 6/6 both ways.
# Register file of the vector unit (HAS_GVU_REGS=1, the data flow controller drives GvuTop through the registers of gvu_core): the
# register-file and AGU unit tests, and the check programs (6 instructions; 9 with three max pools) through the register file with
# the residual add by registers and outside it (HAS_GVU_REGS_ADD=0).
# Number of items of a full run: 105 + 26 (register file group) = 131.
set -u
# The vector-unit knobs default to on in the model (HAS_GVU_TOP=3, HAS_GVU_STALL=1, HAS_GVU_ELEM_CLK=1, HAS_GVU_REGS=1, HAS_GVU_AGU_ND=1).
# The reference values below are those of the path with every knob off, so they are set to 0 here; an entry that checks a knob sets
# it on its own command line (the command-line value wins), and the register-file benches run with HAS_GVU_AGU_ND=0.
export HAS_GVU_TOP=0 HAS_GVU_STALL=0 HAS_GVU_ELEM_CLK=0 HAS_GVU_REGS=0 HAS_GVU_AGU_ND=0
OUT=${1:-/var/tmp/npu_safe/regress_gvu}; MODE=${2:-all}
export LD_LIBRARY_PATH=/usr/lib/x86_64-linux-gnu:${LD_LIBRARY_PATH:-}
mkdir -p "$OUT"
ok=0; bad=0
res() { if [ "$1" = 0 ]; then echo "PASS  $2"; ok=$((ok+1)); else echo "FAIL  $2"; bad=$((bad+1)); fi; }
V=fe_work/has/vectors/gvu; T=tools/has/vec_gvu

echo "== build unit testbenches"
for t in tb_gvu_fused_attn tb_gvu_layernorm tb_gvu_softmax tb_gvu_lut_vectors tb_gvu_vrf tb_gvu_mas tb_has_mmio_compat tb_has_pad_gen; do
  [ -f tools/has/$t.cpp ] || continue
  nice -n 19 g++ -std=c++17 -O2 -Wall -I. tools/has/$t.cpp -o "$OUT/$t" 2> "$OUT/$t.build.log"; res $? "build $t"
done
for t in tb_gvu_quant tb_gvu_elemwise tb_gvu_lut tb_has_dma; do
  nice -n 19 g++ -std=c++17 -O2 -Wall -Wno-unused-variable -I. -I/usr/include tools/has/$t.cpp -lsystemc -lm -pthread -o "$OUT/$t" 2> "$OUT/$t.build.log"; res $? "build $t"
done

echo "== unit checks"
run() { local name=$1; shift; "$@" > "$OUT/$name.log" 2>&1; grep -q "RESULT: PASS" "$OUT/$name.log"; res $? "$name"; }
run tb_gvu_quant "$OUT/tb_gvu_quant"
run tb_gvu_elemwise "$OUT/tb_gvu_elemwise"
run tb_gvu_lut "$OUT/tb_gvu_lut"
run tb_gvu_lut_vectors "$OUT/tb_gvu_lut_vectors" $V $T
run tb_gvu_softmax "$OUT/tb_gvu_softmax" $V $T
run tb_gvu_layernorm "$OUT/tb_gvu_layernorm" $V $T
run tb_gvu_fused_attn "$OUT/tb_gvu_fused_attn" $V $T
run tb_gvu_vrf "$OUT/tb_gvu_vrf"
run tb_has_dma "$OUT/tb_has_dma"
[ -x "$OUT/tb_has_mmio_compat" ] && run tb_has_mmio_compat "$OUT/tb_has_mmio_compat"
[ -x "$OUT/tb_has_pad_gen" ] && run tb_has_pad_gen "$OUT/tb_has_pad_gen"
# Optional: test vectors of the hardware drop (LUT unit and Softmax) on the ported units. GVU_HW_VEC names the directory
# that holds lut_data/ and softmax/; the item is skipped when it does not exist.
HWV=${GVU_HW_VEC:-fe_work/has/vectors/hw}
if [ -f tools/has/tb_rtl_ref_gvu_hwvec.cpp ] && [ -d "$HWV/softmax" ]; then
  nice -n 19 g++ -std=c++17 -O2 -Wall -I. tools/has/tb_rtl_ref_gvu_hwvec.cpp -o "$OUT/tb_rtl_ref_gvu_hwvec" 2> "$OUT/tb_rtl_ref_gvu_hwvec.build.log"; res $? "build tb_rtl_ref_gvu_hwvec"
  run tb_rtl_ref_gvu_hwvec "$OUT/tb_rtl_ref_gvu_hwvec" "$HWV"
fi
# GvuTop (GEMM_FUSED, residual add) against the model's cycle-level units, random data over the whole ranges
if [ -f tools/has/tb_gvu_top_vs_model.cpp ] && [ -f has/rtl_ref_gvu_top.h ]; then
  nice -n 19 g++ -std=c++17 -O2 -Wall -I. tools/has/tb_gvu_top_vs_model.cpp -o "$OUT/tb_gvu_top_vs_model" 2> "$OUT/tb_gvu_top_vs_model.build.log"; res $? "build tb_gvu_top_vs_model"
  run tb_gvu_top_vs_model "$OUT/tb_gvu_top_vs_model" 12 1
  grep -q "RESULT: PASS (runs that differ or did not finish: 0 of 51)" "$OUT/tb_gvu_top_vs_model.log"; res $? "GvuTop vs model: 51 runs (GEMM tile, stream mode, residual add incl. last-row lane mask), 0 differ"
fi
# Ported blocks against the RTL: self-checks of group 2 (load/store unit included) and the digest of the RTL replay
if [ -f tools/has/tb_rtl_ref_gvu_g2.cpp ]; then
  nice -n 19 g++ -std=c++17 -O2 -I. tools/has/tb_rtl_ref_gvu_g2.cpp -o "$OUT/tb_rtl_ref_gvu_g2" 2> "$OUT/tb_rtl_ref_gvu_g2.build.log" &&
    "$OUT/tb_rtl_ref_gvu_g2" > "$OUT/tb_rtl_ref_gvu_g2.log" 2>&1 && grep -q "RESULT: PASS" "$OUT/tb_rtl_ref_gvu_g2.log"
  res $? "tb_rtl_ref_gvu_g2 (vector-unit blocks ported from the RTL: $(grep -o 'checks [0-9]*, mismatches [0-9]*' "$OUT/tb_rtl_ref_gvu_g2.log" | tail -1))"
fi
if [ -f tools/has/check_rtl_trace.sh ]; then
  nice -n 19 bash tools/has/check_rtl_trace.sh "$OUT/rtl_trace" > "$OUT/rtl_trace.log" 2>&1; grep -q "RESULT: PASS" "$OUT/rtl_trace.log"
  res $? "check_rtl_trace.sh (ported blocks give the outputs of the RTL simulation: $(grep -o 'files [0-9]*, beats [0-9]*, files that differ [0-9]*' "$OUT/rtl_trace.log" | tail -1))"
fi
if [ -x "$OUT/tb_gvu_mas" ]; then
  python3 tools/has/mas_ref.py "$OUT/mas_vec" > "$OUT/mas_ref.log" 2>&1; res $? "mas_ref.py writes the reference vectors"
  run tb_gvu_mas "$OUT/tb_gvu_mas" "$OUT/mas_vec"
fi
# Register file of the vector unit (rtl_ref_gvu_config_regs.h, port of gvu_config_regs.sv with the register proposals 9..15) and the
# multi-dimensional address generator with the move operation (gvu_agu_nd*.h): self-checking unit tests
if [ -f tools/has/tb_rtl_ref_gvu_config_regs.cpp ]; then
  nice -n 19 g++ -std=c++17 -O2 -Wall -I. tools/has/tb_rtl_ref_gvu_config_regs.cpp -o "$OUT/tb_rtl_ref_gvu_config_regs" 2> "$OUT/tb_rtl_ref_gvu_config_regs.build.log"; res $? "build tb_rtl_ref_gvu_config_regs"
  run tb_rtl_ref_gvu_config_regs "$OUT/tb_rtl_ref_gvu_config_regs"
fi
if [ -f tools/has/tb_gvu_agu_nd.cpp ] && [ -f tools/has/tb_gvu_agu_nd_move.cpp ]; then
  for t in tb_gvu_agu_nd tb_gvu_agu_nd_move; do
    nice -n 19 g++ -std=c++17 -O2 -Wall -Wextra -I. tools/has/$t.cpp -o "$OUT/$t" 2> "$OUT/$t.build.log"; res $? "build $t"
  done
  run tb_gvu_agu_nd "$OUT/tb_gvu_agu_nd"
  run tb_gvu_agu_nd_move "$OUT/tb_gvu_agu_nd_move"
fi
if [ "$MODE" = "--unit-only" ]; then echo "RESULT: $ok passed, $bad failed"; exit $bad; fi

echo "== instruction path"
F="-std=c++17 -O2 -DSAURIA_DEBUG=0 -DSAURIA_CORE_BACKEND_RTL_REF -DFX1_A3_SRAM_BACKDOOR_LOAD -I. -I/usr/include"
nice -n 19 g++ $F -DFX1_NO_PERF tools/has/tb_has_npu_top.cpp -lsystemc -lm -pthread -o "$OUT/tb_has_npu_top" 2> "$OUT/top.build.log"; res $? "build tb_has_npu_top (default, -DFX1_NO_PERF)"
nice -n 19 g++ $F -DFE_METRICS -fsyntax-only tools/has/tb_has_npu_top.cpp 2> "$OUT/top_metrics.build.log"; res $? "tb_has_npu_top compiles in the metrics variant (-DFE_METRICS, syntax only)"
D=fe_work/has
"$OUT/tb_has_npu_top" $D/rce_gate > "$OUT/rce.log" 2>&1
grep -q "RESULT: PASS (steps 14" "$OUT/rce.log"; res $? "transformer check 14/14"
grep "sim cycles" "$OUT/rce.log" | tail -1
grep "RCE:" "$OUT/rce.log" | tail -1
HAS_SPEC=v47ref "$OUT/tb_has_npu_top" $D/rce_gate > "$OUT/rce_v47ref.log" 2>&1
grep -q "RESULT: PASS (steps 14" "$OUT/rce_v47ref.log" && grep -q "cycles 250885 " "$OUT/rce_v47ref.log"; res $? "transformer check with HAS_SPEC=v47ref: 14/14, 250885 cycles (configuration before the MAS)"
"$OUT/tb_has_npu_top" $D/insts_pe3 --first 40 --count 2 > "$OUT/winD.log" 2>&1
grep -q "RESULT: PASS" "$OUT/winD.log" && grep -q "sim cycles 1658986 " "$OUT/winD.log"; res $? "window D = 1658986 cycles"
# GvuTop connected to the instruction path (has/gvu_top_bridge.h, environment variable HAS_GVU_TOP; off by default).
# Instructions 86-88 of YOLOv8m (two SiLU layers): the epilogue beats are dumped from the cycle-level pipeline and replayed
# on GvuTop outside the core, then run on GvuTop inside the core; HAS_GVU_TOP=2 also charges the table load of GvuTop's
# path (DMA of 256 bytes + 5 cycles) instead of 4096 host-port cycles per SiLU layer. About 3 minutes per run.
if [ -f has/gvu_top_bridge.h ]; then
  epi() { grep -h "$1" "$2" | grep -q "lanes *108544 | differ[a-z ]* 0 |"; }
  nice -n 19 g++ -std=c++17 -O2 -Wall -I. tools/has/tb_gvu_top_replay.cpp -o "$OUT/tb_gvu_top_replay" 2> "$OUT/tb_gvu_top_replay.build.log"; res $? "build tb_gvu_top_replay"
  rm -f "$OUT/obp86.dump"
  HAS_OBP_RTL=1 HAS_OBP_DUMP="$OUT/obp86.dump" "$OUT/tb_has_npu_top" $D/insts_pe3 --first 86 --count 3 > "$OUT/i86_obp.log" 2>&1
  grep -q "RESULT: PASS (steps 3" "$OUT/i86_obp.log" && grep -q "sim cycles 280003 " "$OUT/i86_obp.log" && epi "^\[obp-rtl\] GEMM_FUSED" "$OUT/i86_obp.log" && grep -q "beats written to HAS_OBP_DUMP: 3392" "$OUT/i86_obp.log"; res $? "instructions 86-88 with HAS_OBP_RTL=1: 3/3, 280003 cycles, 108544 lanes 0 differ, 3392 beats dumped"
  "$OUT/tb_gvu_top_replay" "$OUT/obp86.dump" > "$OUT/gvu_top_replay.log" 2>&1
  grep -q "RESULT: PASS" "$OUT/gvu_top_replay.log"; res $? "GvuTop replays the 3392 epilogue beats back to back and one at a time: 0 differ, depth 9"
  rm -f "$OUT/obp86.dump"
  HAS_GVU_TOP=1 "$OUT/tb_has_npu_top" $D/insts_pe3 --first 86 --count 3 > "$OUT/i86_top1.log" 2>&1
  grep -q "RESULT: PASS (steps 3" "$OUT/i86_top1.log" && grep -q "sim cycles 280003 " "$OUT/i86_top1.log" && epi "^\[gvu-top\] GEMM epilogue" "$OUT/i86_top1.log"; res $? "instructions 86-88 with HAS_GVU_TOP=1: 3/3, 280003 cycles (= knobs off), 108544 lanes 0 differ"
  HAS_GVU_TOP=2 "$OUT/tb_has_npu_top" $D/insts_pe3 --first 86 --count 3 > "$OUT/i86_top2.log" 2>&1
  grep -q "RESULT: PASS (steps 3" "$OUT/i86_top2.log" && grep -q "sim cycles 271829 " "$OUT/i86_top2.log" && epi "^\[gvu-top\] GEMM epilogue" "$OUT/i86_top2.log"; res $? "instructions 86-88 with HAS_GVU_TOP=2: 3/3, 271829 cycles (2 tables x (4096 - 9)), 108544 lanes 0 differ"
  # Residual add of every ELEM_WISE instruction of YOLOv8m, replayed from the program's tensors on GvuTop (12 instructions)
  nice -n 19 g++ -std=c++17 -O2 -Wall -I. tools/has/tb_rtl_ref_gvu_replay.cpp -o "$OUT/tb_rtl_ref_gvu_replay" 2> "$OUT/tb_rtl_ref_gvu_replay.build.log"; res $? "build tb_rtl_ref_gvu_replay"
  "$OUT/tb_rtl_ref_gvu_replay" $D/insts_pe3 0 --gvu-top > "$OUT/replay_top.log" 2>&1
  grep -q "RESULT: PASS" "$OUT/replay_top.log" && grep -h "^\[gvu-top\] residual add" "$OUT/replay_top.log" | grep -q "calls *12 | not expressible *0 | lanes *6374400 | differ *0 "; res $? "ELEM_WISE of YOLOv8m on GvuTop: 12 residual adds, 6374400 elements, 0 differ"
  # Max pool on GvuTop (POOLING_MAX, port of the latest hardware RTL drop): the 3 SPPF max pools of YOLOv8m in the
  # channel groups of the default Scratchpad (21 groups of 14 channels each), 184 824 GvuTop cycles per instruction
  grep -h "^\[gvu-top\] max pool" "$OUT/replay_top.log" | grep -q "calls *63 | not expressible *0 | lanes *345600 | differ *0 | GvuTop cycles *554472 "; res $? "MAX_POOL of YOLOv8m on GvuTop: 3 SPPF, 63 groups, 345600 elements, 0 differ, 554472 cycles"
fi
# Max pool of GvuTop against plain max pool (generated cases, the YOLOv8m SPPF case, the socket incl. shapes it must refuse)
# and, when GVU_HW_MAXPOOL names the target/test/maxpool directory of the hardware drop, against the 9 golden sets of HW
if [ -f tools/has/tb_gvu_top_maxpool.cpp ]; then
  nice -n 19 g++ -std=c++17 -O2 -Wall -I. tools/has/tb_gvu_top_maxpool.cpp -o "$OUT/tb_gvu_top_maxpool" 2> "$OUT/tb_gvu_top_maxpool.build.log"; res $? "build tb_gvu_top_maxpool"
  MPV=${GVU_HW_MAXPOOL:--}; [ "$MPV" != "-" ] && [ ! -d "$MPV" ] && MPV=-
  run tb_gvu_top_maxpool "$OUT/tb_gvu_top_maxpool" "$MPV" 1
fi
# ---- HAS_GVU_TOP=3: GvuTop on the clock of the core (has/gvu_top_stream.h, docs/GVU_TOP_CORE_INTEGRATION.md, section 5).
# Cycle bands: level A with HAS_GVU_TOP=2, less up to 12 cycles per core pass for the fixed tail that level B removes.
echo "== level B: stream unit test"
nice -n 19 g++ -std=c++17 -O2 -Wall -Wno-unused-variable -I. -I/usr/include tools/has/tb_gvu_top_stream.cpp -lsystemc -lm -pthread -o "$OUT/tb_gvu_top_stream" 2> "$OUT/tb_gvu_top_stream.build.log"; res $? "build tb_gvu_top_stream"
"$OUT/tb_gvu_top_stream" before > "$OUT/stream_before.log" 2>&1; grep -q "RESULT: PASS" "$OUT/stream_before.log"; res $? "stream unit test, hook before the tap"
"$OUT/tb_gvu_top_stream" after > "$OUT/stream_after.log" 2>&1; grep -q "RESULT: PASS" "$OUT/stream_after.log"; res $? "stream unit test, hook after the tap"
"$OUT/tb_gvu_top_stream" elem > "$OUT/stream_elem.log" 2>&1; grep -q "RESULT: PASS (cases not as expected: 0 of 12)" "$OUT/stream_elem.log"; res $? "residual add and max pool as jobs on the clock = call style: values, cycles, runs, resets, thread time (12 cases)"
[ "$(grep -h 'trace checksum' "$OUT/stream_before.log" | sed 's/.*packet) //;s/ over.*//')" = "$(grep -h 'trace checksum' "$OUT/stream_after.log" | sed 's/.*packet) //;s/ over.*//')" ]; res $? "same trace of the packets in both orders of the processes"
grep -q "trace checksum (push, latch, result of every packet) 0aa7538aad238ffb over 112 packets" "$OUT/stream_before.log"; res $? "stream unit test: trace checksum of the default depth 9 (0aa7538aad238ffb)"

# ---- GEMM_FUSED parameters of GvuTop that follow open hardware choices: stream depth (default 9, the hardware RTL measures
# 11) and the narrowing after the round-shift (has::Knobs::req_narrow SAT16 / WRAP16), tile and stream mode
echo "== GvuTop GEMM_FUSED parameters: stream depth and narrowing"
nice -n 19 g++ -std=c++17 -O2 -Wall -I. tools/has/tb_gvu_top_params.cpp -o "$OUT/tb_gvu_top_params" 2> "$OUT/tb_gvu_top_params.build.log"; res $? "build tb_gvu_top_params"
run tb_gvu_top_params "$OUT/tb_gvu_top_params" 8 1
grep -q "RESULT: PASS (runs not as expected: 0 of 25)" "$OUT/tb_gvu_top_params.log"; res $? "depth 11 = depth 9 beat by beat (latency 11 / 9); SAT16 and WRAP16 = has::requant in tile and stream mode"
nice -n 19 g++ -std=c++17 -O2 -Wall -DGVU_GEMM_STREAM_DEPTH=11 -I. tools/has/tb_gvu_top_params.cpp -o "$OUT/tb_gvu_top_params_d11" 2> "$OUT/tb_gvu_top_params_d11.build.log"; res $? "build tb_gvu_top_params with GVU_GEMM_STREAM_DEPTH=11"
run tb_gvu_top_params_d11 "$OUT/tb_gvu_top_params_d11" 8 1
run tb_gvu_top_params_zp "$OUT/tb_gvu_top_params" zp 1
grep -q "not expressible 361 (expected 361; the case ZP_OUT = 200 with one beat counts 1)" "$OUT/tb_gvu_top_params_zp.log"; res $? "zero point of GEMM_FUSED = 8 bits of the RTL register: int8 taken, 0 differ; outside int8 not expressible (361 of 721 beats, ZP_OUT 200 one beat = 1)"
nice -n 19 g++ -std=c++17 -O2 -Wall -Wno-unused-variable -DGVU_GEMM_STREAM_DEPTH=11 -I. -I/usr/include tools/has/tb_gvu_top_stream.cpp -lsystemc -lm -pthread -o "$OUT/tb_gvu_top_stream_d11" 2> "$OUT/tb_gvu_top_stream_d11.build.log"; res $? "build tb_gvu_top_stream with GVU_GEMM_STREAM_DEPTH=11"
"$OUT/tb_gvu_top_stream_d11" before > "$OUT/stream_d11_before.log" 2>&1; grep -q "RESULT: PASS" "$OUT/stream_d11_before.log"; res $? "stream unit test at depth 11, hook before the tap"
"$OUT/tb_gvu_top_stream_d11" after > "$OUT/stream_d11_after.log" 2>&1; grep -q "RESULT: PASS" "$OUT/stream_d11_after.log"; res $? "stream unit test at depth 11, hook after the tap"
grep -q "latch->result 11): 0 of 112" "$OUT/stream_d11_before.log" && grep -q "trace checksum (push, latch, result of every packet) e8fab7eb30d95077 over 112 packets" "$OUT/stream_d11_before.log" && \
  [ "$(grep -h 'trace checksum' "$OUT/stream_d11_before.log")" = "$(grep -h 'trace checksum' "$OUT/stream_d11_after.log")" ]; res $? "stream unit test at depth 11: latch->result 11 for every packet, same trace in both orders (e8fab7eb30d95077)"

# ---- HAS_GVU_REGS=1: the data flow controller configures and starts GvuTop through the register file (has/gvu_regs_dfc.h,
# has/gvu_reg_master.h, has/rtl_ref_gvu_config_regs.h; GEMM_FUSED, max pool and residual add), the layer leaves by the flags of the
# last write of the call. Unit test at three write latencies L (edges per register write): values equal to the call style, register
# sequences decoded as intended, write counts and times, residual add by registers against the call style with both buffers of vbank1.
echo "== register file: unit test"
if [ -f tools/has/tb_gvu_regs_dfc.cpp ]; then
  nice -n 19 g++ -std=c++17 -O2 -Wall -Wno-unused-variable -I. -I/usr/include tools/has/tb_gvu_regs_dfc.cpp -lsystemc -lm -pthread -o "$OUT/tb_gvu_regs_dfc" 2> "$OUT/tb_gvu_regs_dfc.build.log"; res $? "build tb_gvu_regs_dfc"
  for L in 2 4 7; do
    "$OUT/tb_gvu_regs_dfc" $L > "$OUT/regs_dfc_L$L.log" 2>&1; grep -q "RESULT: PASS (errors 0)" "$OUT/regs_dfc_L$L.log"; res $? "register file by the data flow controller, $L edges per write: values = call style, sequences, write counts and times, residual add, F1' flags"
  done
  grep -q "residual add by registers: runs [0-9]*, runs whose configuration read back from the register file differs from the call style 0," "$OUT/regs_dfc_L4.log"; res $? "register file unit test: the configuration of every residual add run read back from the registers equals the call style's"
fi

echo "== level B: check program of the instruction forms (6 instructions), levels 0 / 1 / 3"
rm -rf "$OUT/ref_gate" "$OUT"/snap_*; mkdir -p "$OUT/snap_0" "$OUT/snap_3"
python3 tools/has/make_ref_gate.py "$OUT/ref_gate" > /dev/null && python3 tools/has/ref_program.py "$OUT/ref_gate" --image "$OUT/ref_gate/dram_init.bin" --write-ref "$OUT/ref_gate/dram_golden.bin" > /dev/null 2>&1
FE_SNAPSHOT_DIR="$OUT/snap_0" "$OUT/tb_has_npu_top" "$OUT/ref_gate" > "$OUT/gate0.log" 2>&1
grep -q "RESULT: PASS (steps 6" "$OUT/gate0.log" && grep -q "sim cycles 47602 " "$OUT/gate0.log"; res $? "check program, knobs off: 6/6, 47602 cycles"
HAS_GVU_TOP=1 HAS_GVU_TOP_DUMP="$OUT/gate_dump1.txt" "$OUT/tb_has_npu_top" "$OUT/ref_gate" > "$OUT/gate1.log" 2>&1
grep -q "RESULT: PASS (steps 6" "$OUT/gate1.log" && grep -q "sim cycles 47602 " "$OUT/gate1.log"; res $? "check program, HAS_GVU_TOP=1: 6/6, 47602 cycles"
HAS_GVU_TOP=3 HAS_GVU_TOP_DUMP="$OUT/gate_dump3.txt" FE_SNAPSHOT_DIR="$OUT/snap_3" "$OUT/tb_has_npu_top" "$OUT/ref_gate" > "$OUT/gate3.log" 2>&1
grep -q "RESULT: PASS (steps 6" "$OUT/gate3.log" && grep -q "sim cycles 39361 " "$OUT/gate3.log"; res $? "check program, HAS_GVU_TOP=3: 6/6, 39361 cycles"
cmp -s "$OUT/gate_dump1.txt" "$OUT/gate_dump3.txt"; res $? "check program: every epilogue beat of level 3 equals level 1 (2672 beats, dump files equal)"
cmp -s "$OUT/snap_0/dram_snapshot.bin" "$OUT/snap_3/dram_snapshot.bin"; res $? "check program: DRAM image of level 3 equals the image of the knobs-off run"
mkdir -p "$OUT/snap_clk"; HAS_GVU_TOP=3 HAS_GVU_ELEM_CLK=1 FE_SNAPSHOT_DIR="$OUT/snap_clk" "$OUT/tb_has_npu_top" "$OUT/ref_gate" > "$OUT/gate_clk.log" 2>&1
grep -q "RESULT: PASS (steps 6" "$OUT/gate_clk.log" && grep -q "sim cycles 39361 " "$OUT/gate_clk.log" && grep -q "jobs 3 (failed 0), ticks 450, GvuTop cycles of the jobs 450, ticks after done to IDLE 0, jobs not started at the edge after the request 0" "$OUT/gate_clk.log" && cmp -s "$OUT/snap_0/dram_snapshot.bin" "$OUT/snap_clk/dram_snapshot.bin"; res $? "check program, HAS_GVU_ELEM_CLK=1: 6/6, 39361 cycles (= call style), 3 jobs 450 ticks, DRAM = knobs off"
grep -h "^\[gvu-stream\] packets" "$OUT/gate3.log" | grep -q "pushed 2672 .*latched 2672, results 2672, lanes 12928, differ from the model 0"; res $? "check program level 3: 2672 packets, 12928 lanes, 0 differ"
grep -h "^\[gvu-stream\] FIFO" "$OUT/gate3.log" | grep -q "max depth 1, STALL NEEDED 0"; res $? "check program level 3: queue 1, STALL NEEDED 0"
! grep -q "^\[gvu-top\] GEMM epilogue" "$OUT/gate3.log"; res $? "check program level 3: the call-style epilogue is not used"

# ---- level B: the core stops on o_stream_stall (HAS_GVU_STALL=1, as psm_top.sv: FIFO of 4 packets full and none leaving -> the SRAM-C
# write is blocked and the core holds). HAS_GVU_STREAM_HOLD (test only) holds the ready of the unit low to fill the FIFO.
echo "== level B: core stall on the stream FIFO"
mkdir -p "$OUT/snap_st"
HAS_GVU_TOP=3 HAS_GVU_STALL=1 "$OUT/tb_has_npu_top" "$OUT/ref_gate" > "$OUT/gate_st0.log" 2>&1
grep -q "RESULT: PASS (steps 6" "$OUT/gate_st0.log" && grep -q "sim cycles 39361 " "$OUT/gate_st0.log" && grep -q "core stall cycles 0 " "$OUT/gate_st0.log"; res $? "check program, core stall on, no hold: 6/6, 39361 cycles, 0 core stall cycles"
HAS_GVU_TOP=3 HAS_GVU_STREAM_HOLD=6000,6300 "$OUT/tb_has_npu_top" "$OUT/ref_gate" > "$OUT/gate_hold_off.log" 2>&1
grep -q "RESULT: PASS (steps 6" "$OUT/gate_hold_off.log" && grep -q "sim cycles 39361 " "$OUT/gate_hold_off.log" && grep -q "STALL NEEDED 28 " "$OUT/gate_hold_off.log"; res $? "check program, core stall off, ready held 300 edges: core not stopped, 28 packets taken with the FIFO full, 39361 cycles"
HAS_GVU_TOP=3 HAS_GVU_STALL=2 HAS_GVU_STREAM_HOLD=6000,6300 "$OUT/tb_has_npu_top" "$OUT/ref_gate" > "$OUT/gate_hold_obs.log" 2>&1
grep -q "edges with a stall computed 28 .*with the FIFO full 28 .*-> same edges; write read before the step checked [0-9]*, mismatched 0" "$OUT/gate_hold_obs.log"; res $? "check program, stall observed only: computed at the same 28 edges as the packets taken with the FIFO full; write read before the step = write made"
HAS_GVU_TOP=3 HAS_GVU_STALL=1 HAS_GVU_STREAM_HOLD=6000,6300 HAS_GVU_TOP_DUMP="$OUT/gate_dump_st.txt" FE_SNAPSHOT_DIR="$OUT/snap_st" "$OUT/tb_has_npu_top" "$OUT/ref_gate" > "$OUT/gate_st.log" 2>&1
grep -q "RESULT: PASS (steps 6" "$OUT/gate_st.log" && grep -q "sim cycles 39629 " "$OUT/gate_st.log" && grep -q "max depth 4, STALL NEEDED 0 " "$OUT/gate_st.log" && grep -q "core stall cycles 277 .*mismatched 0" "$OUT/gate_st.log" && grep -q "core busy (start to done) 33118" "$OUT/gate_st.log"; res $? "check program, core stall on, ready held 300 edges: FIFO max 4, no packet over, core held 277 cycles (core busy 32841 + 277), 39629 cycles"
grep -q "OBP vectors 2672" "$OUT/gate_st.log" && grep -h "^\[gvu-stream\] packets" "$OUT/gate_st.log" | grep -q "pushed 2672 .*latched 2672, results 2672, lanes 12928, differ from the model 0"; res $? "check program, core stall on: 2672 packets = 2672 writes of the last Cin pass, none lost or repeated, 0 differ"
cmp -s "$OUT/gate_dump1.txt" "$OUT/gate_dump_st.txt" && cmp -s "$OUT/snap_0/dram_snapshot.bin" "$OUT/snap_st/dram_snapshot.bin"; res $? "check program, core stall on: every epilogue beat equals level 1, DRAM image equals the knobs-off run"

# ---- the data flow controller drives GvuTop through the register file (HAS_GVU_REGS=1). The register writes cost HAS_GVU_REG_LAT edges
# each (default 4, an estimate); the values equal level 3, the cycles are level 3 plus the writes. Each run is also checked for the layer
# exits by the flags of the last write of the call (no fallback), the flag on exactly one packet per layer, the configuration of the
# residual add read back from the registers equal to the call style's. HAS_GVU_REGS_ADD=0 leaves the residual add outside the register file.
echo "== register file: check programs through the registers"
regs_ok() {   # log exits writes busy : the register file run is clean and counts what the sequences say
  grep -q "RESULT: PASS (steps" "$1" && grep -q "layer exits by oc_last & oc_tile_last $2 (model stop as fallback 0, timeouts 0)" "$1" && \
    grep -q "register writes $3, edges the DFC waited on the write port $4," "$1" && grep -q "calls with the flag not on the one last packet 0" "$1" && \
    grep -q "STALL NEEDED 0" "$1" && ! grep -q "<== FAIL" "$1"; }
mkdir -p "$OUT/snap_regs" "$OUT/snap_regs0"
HAS_GVU_TOP=3 HAS_GVU_REGS=1 HAS_GVU_TOP_DUMP="$OUT/gate_dump_regs.txt" FE_SNAPSHOT_DIR="$OUT/snap_regs" "$OUT/tb_has_npu_top" "$OUT/ref_gate" > "$OUT/gate_regs.log" 2>&1
regs_ok "$OUT/gate_regs.log" 4 44 176 && grep -q "sim cycles 39562 " "$OUT/gate_regs.log" && grep -q "residual add by registers: runs 3, runs whose configuration read back from the register file differs from the call style 0," "$OUT/gate_regs.log" && grep -q "jobs 3 (failed 0), ticks 450, " "$OUT/gate_regs.log"; res $? "check program through the register file: 6/6, 39562 cycles, 4 layers leave by the flags, 44 register writes, residual add by registers 3 runs, configuration = call style"
cmp -s "$OUT/gate_dump3.txt" "$OUT/gate_dump_regs.txt"; res $? "check program through the register file: every epilogue beat equals level 3 (dump files equal)"
cmp -s "$OUT/snap_0/dram_snapshot.bin" "$OUT/snap_regs/dram_snapshot.bin"; res $? "check program through the register file: DRAM image equals the knobs-off run"
HAS_GVU_TOP=3 HAS_GVU_REGS=1 HAS_GVU_REGS_ADD=0 HAS_GVU_TOP_DUMP="$OUT/gate_dump_regs0.txt" FE_SNAPSHOT_DIR="$OUT/snap_regs0" "$OUT/tb_has_npu_top" "$OUT/ref_gate" > "$OUT/gate_regs0.log" 2>&1
regs_ok "$OUT/gate_regs0.log" 4 14 56 && grep -q "sim cycles 39428 " "$OUT/gate_regs0.log"; res $? "check program, register file with the residual add outside (HAS_GVU_REGS_ADD=0): 6/6, 39428 cycles, 14 register writes"
cmp -s "$OUT/gate_dump3.txt" "$OUT/gate_dump_regs0.txt"; res $? "check program, residual add outside the register file: every epilogue beat equals level 3"
cmp -s "$OUT/snap_0/dram_snapshot.bin" "$OUT/snap_regs0/dram_snapshot.bin"; res $? "check program, residual add outside the register file: DRAM image equals the knobs-off run"

# the same program with three max pools (5x5 twice in a row as SPPF, 3x3): 9 instructions
rm -rf "$OUT/ref_gate_mp" "$OUT"/snap_mp*; mkdir -p "$OUT/snap_mp0" "$OUT/snap_mp3" "$OUT/snap_mpr" "$OUT/snap_mpr0"
# ref_program.py also compares against the input image given by --image and so reports a mismatch (exit 1) while it writes the
# reference image; the item checks that the program was generated and that the reference image was written.
python3 tools/has/make_ref_gate_mp.py "$OUT/ref_gate_mp" > /dev/null && { python3 tools/has/ref_program.py "$OUT/ref_gate_mp" --image "$OUT/ref_gate_mp/dram_init.bin" --write-ref "$OUT/ref_gate_mp/dram_golden.bin" > /dev/null 2>&1; [ -s "$OUT/ref_gate_mp/dram_golden.bin" ]; }; res $? "check program with max pools (9 instructions): generated, reference image written"
FE_SNAPSHOT_DIR="$OUT/snap_mp0" "$OUT/tb_has_npu_top" "$OUT/ref_gate_mp" > "$OUT/gate_mp0.log" 2>&1
grep -q "RESULT: PASS (steps 9" "$OUT/gate_mp0.log" && grep -q "sim cycles 62965 " "$OUT/gate_mp0.log"; res $? "check program with max pools, knobs off: 9/9, 62965 cycles"
HAS_GVU_TOP=3 HAS_GVU_TOP_DUMP="$OUT/gate_mp_dump3.txt" FE_SNAPSHOT_DIR="$OUT/snap_mp3" "$OUT/tb_has_npu_top" "$OUT/ref_gate_mp" > "$OUT/gate_mp3.log" 2>&1
grep -q "RESULT: PASS (steps 9" "$OUT/gate_mp3.log" && grep -q "sim cycles 68124 " "$OUT/gate_mp3.log" && grep -h "^\[gvu-stream\] max pool" "$OUT/gate_mp3.log" | grep -q "calls 4 | not expressible 0 | lanes 10368 | differ 0 | runs 4 "; res $? "check program with max pools, HAS_GVU_TOP=3: 9/9, 68124 cycles, 4 max pool runs, 10368 lanes, 0 differ"
HAS_GVU_TOP=3 HAS_GVU_REGS=1 HAS_GVU_TOP_DUMP="$OUT/gate_mp_dump_regs.txt" FE_SNAPSHOT_DIR="$OUT/snap_mpr" "$OUT/tb_has_npu_top" "$OUT/ref_gate_mp" > "$OUT/gate_mp_regs.log" 2>&1
regs_ok "$OUT/gate_mp_regs.log" 4 60 240 && grep -q "sim cycles 68392 " "$OUT/gate_mp_regs.log" && grep -q "max pool runs 4," "$OUT/gate_mp_regs.log" && grep -h "^\[gvu-stream\] max pool" "$OUT/gate_mp_regs.log" | grep -q "differ 0 "; res $? "check program with max pools through the register file: 9/9, 68392 cycles, 60 register writes, 4 max pool runs by registers, 0 differ"
cmp -s "$OUT/gate_mp_dump3.txt" "$OUT/gate_mp_dump_regs.txt"; res $? "check program with max pools through the register file: every epilogue beat equals level 3"
cmp -s "$OUT/snap_mp0/dram_snapshot.bin" "$OUT/snap_mpr/dram_snapshot.bin"; res $? "check program with max pools through the register file: DRAM image equals the knobs-off run"
HAS_GVU_TOP=3 HAS_GVU_REGS=1 HAS_GVU_REGS_ADD=0 HAS_GVU_TOP_DUMP="$OUT/gate_mp_dump_regs0.txt" FE_SNAPSHOT_DIR="$OUT/snap_mpr0" "$OUT/tb_has_npu_top" "$OUT/ref_gate_mp" > "$OUT/gate_mp_regs0.log" 2>&1
regs_ok "$OUT/gate_mp_regs0.log" 4 30 120 && grep -q "sim cycles 68258 " "$OUT/gate_mp_regs0.log" && grep -q "max pool runs 4," "$OUT/gate_mp_regs0.log"; res $? "check program with max pools, residual add outside the register file: 9/9, 68258 cycles, 30 register writes"
cmp -s "$OUT/gate_mp_dump3.txt" "$OUT/gate_mp_dump_regs0.txt"; res $? "check program with max pools, residual add outside the register file: every epilogue beat equals level 3"
cmp -s "$OUT/snap_mp0/dram_snapshot.bin" "$OUT/snap_mpr0/dram_snapshot.bin"; res $? "check program with max pools, residual add outside the register file: DRAM image equals the knobs-off run"

echo "== level B: instructions 86-88 and window D (YOLOv8m), level 3 against level 1"
if [ -d $D/insts_pe3 ]; then
  band() {   # name log lo hi : "sim cycles N" in [lo, hi]
    local n; n=$(grep -h "sim cycles" "$2" | tail -1 | sed 's/.*sim cycles \([0-9]*\).*/\1/'); [ -n "$n" ] && [ "$n" -ge "$3" ] && [ "$n" -le "$4" ]; res $? "$1: $n cycles in [$3, $4]"; }
  HAS_GVU_TOP=1 HAS_GVU_TOP_DUMP="$OUT/i86_dump1.txt" "$OUT/tb_has_npu_top" $D/insts_pe3 --first 86 --count 3 > "$OUT/i86_top1.log" 2>&1
  HAS_GVU_TOP=3 HAS_GVU_TOP_DUMP="$OUT/i86_dump3.txt" "$OUT/tb_has_npu_top" $D/insts_pe3 --first 86 --count 3 > "$OUT/i86_top3.log" 2>&1
  P=$(grep -h "core passes" "$OUT/i86_top3.log" | head -1 | sed 's/.*core passes \([0-9]*\) for.*/\1/')
  grep -q "RESULT: PASS (steps 3" "$OUT/i86_top3.log"; res $? "instructions 86-88 with HAS_GVU_TOP=3: 3/3"
  cmp -s "$OUT/i86_dump1.txt" "$OUT/i86_dump3.txt"; res $? "instructions 86-88: 3392 epilogue beats of level 3 equal level 1 (dump files equal)"
  grep -h "^\[gvu-stream\] packets" "$OUT/i86_top3.log" | grep -q "pushed 3392 .*lanes 108544, differ from the model 0"; res $? "instructions 86-88 level 3: 3392 packets, 108544 lanes, 0 differ"
  grep -h "^\[gvu-stream\] FIFO" "$OUT/i86_top3.log" | grep -q "STALL NEEDED 0"; res $? "instructions 86-88 level 3: STALL NEEDED 0"
  band "instructions 86-88 level 3" "$OUT/i86_top3.log" $((271829 - 12 * P)) $((271829 + 10))
  HAS_GVU_TOP=1 HAS_GVU_TOP_DUMP="$OUT/winD_dump1.txt" "$OUT/tb_has_npu_top" $D/insts_pe3 --first 40 --count 2 > "$OUT/winD_top1.log" 2>&1
  HAS_GVU_TOP=3 HAS_GVU_TOP_DUMP="$OUT/winD_dump3.txt" "$OUT/tb_has_npu_top" $D/insts_pe3 --first 40 --count 2 > "$OUT/winD_top3.log" 2>&1
  P=$(grep -h "core passes" "$OUT/winD_top3.log" | head -1 | sed 's/.*core passes \([0-9]*\) for.*/\1/')
  grep -q "RESULT: PASS" "$OUT/winD_top3.log"; res $? "window D with HAS_GVU_TOP=3: PASS"
  cmp -s "$OUT/winD_dump1.txt" "$OUT/winD_dump3.txt"; res $? "window D: epilogue beats of level 3 equal level 1 (dump files equal)"
  grep -h "^\[gvu-stream\] packets" "$OUT/winD_top3.log" | grep -q "lanes 596736, differ from the model 0"; res $? "window D level 3: 596736 lanes, 0 differ"
  grep -h "^\[gvu-stream\] FIFO" "$OUT/winD_top3.log" | grep -q "STALL NEEDED 0"; res $? "window D level 3: STALL NEEDED 0"
  band "window D level 3" "$OUT/winD_top3.log" $((1650477 - 12 * P)) $((1650477 + 10))
fi
python3 tools/has/make_avgpool_gate.py "$OUT/avgpool_gate" > /dev/null && "$OUT/tb_has_npu_top" "$OUT/avgpool_gate" > "$OUT/avg.log" 2>&1
grep -q "RESULT: PASS (steps 8" "$OUT/avg.log"; res $? "AVG_POOL instruction path 8/8"
grep "sim cycles" "$OUT/avg.log" | tail -1
# Convolution padding (padding per side, padding value): golden from explicit loops in make_pad_gate.py, then the
# independent reference tool, the model with the padding staged, and the model with the padding generated by the feeder.
rm -rf "$OUT/pad_gate" "$OUT/pad_rnd"; rm -f "$OUT"/pad_ref.log "$OUT"/pad.log "$OUT"/pad_feeder.log "$OUT"/pad_rnd*.log
python3 tools/has/make_pad_gate.py "$OUT/pad_gate" > /dev/null && python3 tools/has/ref_program.py "$OUT/pad_gate" > "$OUT/pad_ref.log" 2>&1
grep -q "RESULT: MATCH (checked 13: match 13" "$OUT/pad_ref.log"; res $? "padding check program: reference tool 13/13"
"$OUT/tb_has_npu_top" "$OUT/pad_gate" > "$OUT/pad.log" 2>&1
grep -q "RESULT: PASS (steps 13" "$OUT/pad.log"; res $? "padding check program, padding staged 13/13"
HAS_FEEDER_PAD=1 "$OUT/tb_has_npu_top" "$OUT/pad_gate" > "$OUT/pad_feeder.log" 2>&1
grep -q "RESULT: PASS (steps 13" "$OUT/pad_feeder.log" && grep -q "padded by the feeder 30, kept staged although the window reaches outside the image 1$" "$OUT/pad_feeder.log"; res $? "padding check program, padding by the IFMAP feeder 13/13 (30 core passes, 1 kept staged)"
grep "sim cycles" "$OUT/pad.log" "$OUT/pad_feeder.log" | cut -d: -f2- | cut -c1-110
busy() { grep "core busy" "$1" | sed 's/.*done) \([0-9]*\).*/\1/'; }
[ -n "$(busy "$OUT/pad.log")" ] && [ "$(busy "$OUT/pad.log")" = "$(busy "$OUT/pad_feeder.log")" ]; res $? "padding check program: core busy cycles equal with both ways of padding ($(busy "$OUT/pad.log"))"
# Random layers (12 random + 3 fixed instructions; make_pad_gate.py --count 40 gives the long version): several
# output-channel tiles, tiles with and without padding in one layer, stride 2 with 32 positions per context, a tile that
# nearly fills one input buffer.
python3 tools/has/make_pad_gate.py "$OUT/pad_rnd" --set random --seed 1 --count 12 > /dev/null && python3 tools/has/ref_program.py "$OUT/pad_rnd" > "$OUT/pad_rnd_ref.log" 2>&1
grep -q "RESULT: MATCH (checked 15: match 15" "$OUT/pad_rnd_ref.log"; res $? "random padding layers: reference tool 15/15"
"$OUT/tb_has_npu_top" "$OUT/pad_rnd" > "$OUT/pad_rnd.log" 2>&1
grep -q "RESULT: PASS (steps 15" "$OUT/pad_rnd.log"; res $? "random padding layers, padding staged 15/15"
HAS_FEEDER_PAD=1 "$OUT/tb_has_npu_top" "$OUT/pad_rnd" > "$OUT/pad_rnd_feeder.log" 2>&1
grep -q "RESULT: PASS (steps 15" "$OUT/pad_rnd_feeder.log" && [ "$(busy "$OUT/pad_rnd.log")" = "$(busy "$OUT/pad_rnd_feeder.log")" ]; res $? "random padding layers, padding by the IFMAP feeder 15/15, core busy cycles equal ($(busy "$OUT/pad_rnd_feeder.log"))"
grep -h "padding:" "$OUT/pad_rnd_feeder.log" | cut -c1-170
# Short contexts (K = kernel positions x input channels from 1 to 10, mostly 32 output channels per tile): the weight
# counter finishes a repetition while the weight FIFO holds it (KNOWN_LIMITATIONS.md, O23).
rm -rf "$OUT/smallk"; rm -f "$OUT"/smallk_ref.log "$OUT"/smallk.log
python3 tools/has/make_pad_gate.py "$OUT/smallk" --set smallk > /dev/null && python3 tools/has/ref_program.py "$OUT/smallk" > "$OUT/smallk_ref.log" 2>&1
grep -q "RESULT: MATCH (checked 19: match 19" "$OUT/smallk_ref.log"; res $? "short-context layers: reference tool 19/19"
"$OUT/tb_has_npu_top" "$OUT/smallk" > "$OUT/smallk.log" 2>&1
grep -q "RESULT: PASS (steps 19" "$OUT/smallk.log"; res $? "short-context layers 19/19"
# Dilation (DILATION register, kernel taps 2 to 9 apart; golden from explicit loops), padding staged and by the feeder.
rm -rf "$OUT/dil_gate"; rm -f "$OUT"/dil_ref.log "$OUT"/dil.log "$OUT"/dil_feeder.log
python3 tools/has/make_pad_gate.py "$OUT/dil_gate" --set dilation > /dev/null && python3 tools/has/ref_program.py "$OUT/dil_gate" > "$OUT/dil_ref.log" 2>&1
grep -q "RESULT: MATCH (checked 13: match 13" "$OUT/dil_ref.log"; res $? "dilation layers: reference tool 13/13"
"$OUT/tb_has_npu_top" "$OUT/dil_gate" > "$OUT/dil.log" 2>&1
grep -q "RESULT: PASS (steps 13" "$OUT/dil.log"; res $? "dilation layers, padding staged 13/13"
HAS_FEEDER_PAD=1 "$OUT/tb_has_npu_top" "$OUT/dil_gate" > "$OUT/dil_feeder.log" 2>&1
# Core busy is NOT equal here: the 1x8 layer with dilation 9 (window 103 columns, real part 40) runs 8 cycles longer with
# the padding by the feeder (8950 -> 8958 on its one tile, every other tile equal), so both values are checked.
grep -q "RESULT: PASS (steps 13" "$OUT/dil_feeder.log" && [ "$(busy "$OUT/dil.log")" = 247370 ] && [ "$(busy "$OUT/dil_feeder.log")" = 247378 ]; res $? "dilation layers, padding by the IFMAP feeder 13/13, core busy 247370 staged / 247378 by the feeder"
grep -h "padding:" "$OUT/dil_feeder.log" | cut -c1-170
# Random dilation layers, short version (6 layers of seed 1; --count 30 and seeds 2, 3 give the long runs). Core busy is
# printed, not compared: it may differ by a few cycles between the two ways of padding.
rm -rf "$OUT/dil_rnd"; rm -f "$OUT"/dil_rnd*.log
python3 tools/has/make_pad_gate.py "$OUT/dil_rnd" --set dilrandom --seed 1 --count 6 > /dev/null && python3 tools/has/ref_program.py "$OUT/dil_rnd" > "$OUT/dil_rnd_ref.log" 2>&1
grep -q "RESULT: MATCH (checked 6: match 6" "$OUT/dil_rnd_ref.log"; res $? "random dilation layers: reference tool 6/6"
"$OUT/tb_has_npu_top" "$OUT/dil_rnd" > "$OUT/dil_rnd.log" 2>&1
grep -q "RESULT: PASS (steps 6" "$OUT/dil_rnd.log"; res $? "random dilation layers, padding staged 6/6"
HAS_FEEDER_PAD=1 "$OUT/tb_has_npu_top" "$OUT/dil_rnd" > "$OUT/dil_rnd_feeder.log" 2>&1
grep -q "RESULT: PASS (steps 6" "$OUT/dil_rnd_feeder.log"; res $? "random dilation layers, padding by the IFMAP feeder 6/6 (core busy $(busy "$OUT/dil_rnd.log") staged, $(busy "$OUT/dil_rnd_feeder.log") by the feeder)"
echo "RESULT: $ok passed, $bad failed"
exit $bad
